function lvOwners(tid){tid=String(tid||'');if(!tid||!D||!D.owners)return[];const o=D.owners.find(ow=>(ow.teams||[]).some(x=>String(x.tid)===tid));return o&&o.name?[o.name]:[]}
function lvShortOf(id,fb){const t=(D&&D.teams&&D.teams[id])||{};return t.short||t.abbr||t.name||fb||''}
function lvFromEvent(e){const ev=lvParse(e);if(!ev||!ev.home||!ev.away||!ev.home.id||!ev.away.id)return null;if(ev.status==='other')return null;
  const raw=(e.competitions||[])[0]||{},comp=id=>(raw.competitors||[]).find(x=>String((x.team||{}).id)===String(id))||{};
  const short=id=>{const tm=(comp(id).team||{});return lvShortOf(id,tm.abbreviation||tm.shortDisplayName||tm.location||'')};
  const side=s=>{const ow=lvOwners(s.id);return{id:String(s.id),score:s.score,seed:s.seed||null,short:short(s.id),owners:ow,pool:!!ow.length,win:!!s.win}};
  const note=(((raw.notes||[])[0])||{}).headline||'',stype=(e.season||{}).type;let kind='reg',round='';
  if(stype===5||/play-?in/i.test(note)){kind='playin';round=note||'Play-In'}
  else if(/NBA Cup/i.test(note)&&(/quarter|semi|champ/i.test(note))){kind='cup';round=/champ/i.test(note)?'Cup Championship':/semi/i.test(note)?'Cup Semifinals':'Cup Quarterfinals'}
  else if(stype===3){kind='playoff';round=note.split(' - ').pop()||note}
  const start=ev.start||e.date||null,day=start?lvEtDay(start):(e.date||'').slice(0,10);
  const g={id:String(ev.id),day,start,status:ev.status,kind,round,neutral:!!raw.neutralSite,home:side(ev.home),away:side(ev.away),line:null,upset:null,src:'espn'};
  g.h2h=!!(g.home.owners.length&&g.away.owners.length&&g.home.owners[0]!==g.away.owners[0]);
  g.civil=!!(g.home.owners.length&&g.away.owners.length&&g.home.owners[0]===g.away.owners[0]);return g}
function lvAdd(g){if(!D||!g)return false;D.games=D.games||[];if(D.games.some(x=>String(x.id)===String(g.id)))return false;D.games.push(g);
  const row=(us,them,site)=>({id:g.id,day:g.day,start:g.start,status:g.status,kind:g.kind,round:g.round,site,opp:them.short,oppId:them.id,us:us.score,them:them.score,res:g.status==='final'&&us.score!=null&&them.score!=null&&us.score!==them.score?(us.score>them.score?'W':'L'):null,src:'espn'});
  const addTG=(us,them,site)=>{const id=String(us.id);if(!D.team_games)D.team_games={};(D.team_games[id]=D.team_games[id]||[]).push(row(us,them,site))};
  addTG(g.home,g.away,'H');addTG(g.away,g.home,'A');if(D.meta)D.meta.games_loaded=(D.games||[]).length;return true}

