function lvEtDay(x){try{const d=x instanceof Date?x:new Date(x);return isNaN(d)? '':ETK.format(d)}catch(e){return ''}}
  const today=lvEtDay(now),tom=lvEtDay(now+24*3600000),nxt=lvEtDay(now+48*3600000),set=new Set([today,tom,nxt].filter(Boolean));
  ((D&&D.games)||[]).forEach(g=>{
    const t=g.start?Date.parse(g.start):NaN,d=!isNaN(t)?lvEtDay(t):(g.day||'');
    if(!d)return;
    if(lvHot(g,now)){set.add(d);return}
    if(g.status!=='final'&&!isNaN(t)&&now-t>=0&&now-t<=7*86400000)set.add(d)
  });
  const pref=d=>d===today?0:d===tom?1:d===nxt?2:3;
  return [...set].sort((a,b)=>pref(a)-pref(b)||(Date.parse(a)-Date.parse(today))-(Date.parse(b)-Date.parse(today))).slice(0,Math.max(LVC.maxDays,4)).sort();

